import re,xml.etree.ElementTree as ET
ns={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
ss=[]
for si in ET.parse('xl/sharedStrings.xml').getroot():
    ss.append(''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t')))
def rd(f):
    out={}
    for c in ET.parse(f).getroot().iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}c'):
        r=c.get('r'); t=c.get('t'); v=c.find('m:v',ns); fo=c.find('m:f',ns)
        val=v.text if v is not None else None
        if t=='s' and val is not None: val=ss[int(val)]
        out[r]=(val, fo.text if fo is not None else None)
    return out
cs=rd('xl/worksheets/sheet3.xml')
for r in range(1,30):
    row=[(col+str(r),cs.get(col+str(r))) for col in 'BCDEFGH' if col+str(r) in cs]
    if row: print(row)
print('F25',cs.get('F25'))
EOF
